# Original bounded audit probe; CPython 3.13.16 is the output oracle.
texts = ['', 'a', 'ab', 'é', 'aé日😀', 'e\u0301', '\0é\0', chr(0xD800), chr(0x10FFFF), '日本', 'ab' * 40, 'aé' * 40]
separators = ['', '-', 'é', '日本', '😀', '\0', 'e\u0301', chr(0xDFFF)]
counts = [-9223372036854775807 - 1, -2, -1, 0, 1, 2, 3, 4, 81, 2**62, 9223372036854775807]
for i, s in enumerate(texts):
    for j, sep in enumerate(separators):
        for n in counts:
            r = s.replace('', sep, n)
            print(i, j, n, ascii(r), len(r), ascii(''.join(list(r))))
        print(i, j, 'default', ascii(s.replace('', sep)))
for bs in [b'', b'ab', b'\xc3\xa9', b'\0\xff\xf0\x9f\x98\x80']:
    for bsep in [b'', b'-', b'\xc3\xa9', b'\0\xff']:
        for n in counts:
            print(repr(bs), repr(bsep), n, repr(bs.replace(b'', bsep, n)))

